import Database from "better-sqlite3";
import { join } from "path";

let dbInstance: Database.Database | null = null;

export function getDb() {
  if (dbInstance) {
    return dbInstance;
  }

  const dbPath = "/home/user/qwik-app/db.sqlite";
  const db = new Database(dbPath);

  // Enable foreign keys
  db.pragma("foreign_keys = ON");

  // Create tables
  db.exec(`
    CREATE TABLE IF NOT EXISTS Product (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      price REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS Coupon (
      code TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      value REAL NOT NULL,
      minSpend REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS CartItem (
      productId INTEGER PRIMARY KEY,
      quantity INTEGER NOT NULL,
      FOREIGN KEY(productId) REFERENCES Product(id)
    );

    CREATE TABLE IF NOT EXISTS ActiveCoupon (
      code TEXT PRIMARY KEY,
      FOREIGN KEY(code) REFERENCES Coupon(code)
    );
  `);

  // Seed data if Product table is empty
  const productCount = db.prepare("SELECT COUNT(*) as count FROM Product").get() as { count: number };
  if (productCount.count === 0) {
    const insertProduct = db.prepare("INSERT INTO Product (id, name, price) VALUES (?, ?, ?)");
    const products = [
      [1, "Laptop", 1000.0],
      [2, "Headphones", 100.0],
      [3, "Mouse", 50.0],
      [4, "Keyboard", 80.0],
    ];
    for (const prod of products) {
      insertProduct.run(prod[0], prod[1], prod[2]);
    }
  }

  // Seed data if Coupon table is empty
  const couponCount = db.prepare("SELECT COUNT(*) as count FROM Coupon").get() as { count: number };
  if (couponCount.count === 0) {
    const insertCoupon = db.prepare("INSERT INTO Coupon (code, type, value, minSpend) VALUES (?, ?, ?, ?)");
    const coupons = [
      ["SAVE10", "PERCENT", 10.0, 100.0],
      ["SAVE20", "PERCENT", 20.0, 200.0],
      ["FLAT15", "FIXED", 15.0, 50.0],
      ["FLAT50", "FIXED", 50.0, 150.0],
      ["BOGOHP", "BOGO", 2.0, 0.0],
      ["BOGOMOUSE", "BOGO", 3.0, 10.0],
    ];
    for (const coup of coupons) {
      insertCoupon.run(coup[0], coup[1], coup[2], coup[3]);
    }
  }

  dbInstance = db;
  return db;
}

import { getDb } from "./db";

export interface CartItem {
  productId: number;
  name: string;
  price: number;
  quantity: number;
  total: number;
}

export interface Coupon {
  code: string;
  type: "PERCENT" | "FIXED" | "BOGO";
  value: number;
  minSpend: number;
}

export interface CartState {
  items: CartItem[];
  subtotal: number;
  coupon: Coupon | null;
  discount: number;
  total: number;
  error: string | null;
}

export function getCartState(customError: string | null = null): CartState {
  const db = getDb();

  // Fetch cart items
  const dbItems = db.prepare(`
    SELECT ci.productId, p.name, p.price, ci.quantity
    FROM CartItem ci
    JOIN Product p ON ci.productId = p.id
    ORDER BY ci.productId ASC
  `).all() as { productId: number; name: string; price: number; quantity: number }[];

  const items: CartItem[] = dbItems.map((item) => ({
    productId: item.productId,
    name: item.name,
    price: item.price,
    quantity: item.quantity,
    total: Math.round(item.price * item.quantity * 100) / 100,
  }));

  // Calculate subtotal
  const subtotal = Math.round(items.reduce((sum, item) => sum + item.total, 0) * 100) / 100;

  // Fetch active coupon
  const activeCouponDb = db.prepare(`
    SELECT ac.code, c.type, c.value, c.minSpend
    FROM ActiveCoupon ac
    JOIN Coupon c ON ac.code = c.code
  `).get() as { code: string; type: string; value: number; minSpend: number } | undefined;

  let coupon: Coupon | null = null;
  let discount = 0;
  let error = customError;

  if (activeCouponDb) {
    // Validate minSpend
    if (subtotal < activeCouponDb.minSpend) {
      // Automatically remove active coupon from the database
      db.prepare("DELETE FROM ActiveCoupon").run();
      error = "Minimum spend not met";
    } else {
      coupon = {
        code: activeCouponDb.code,
        type: activeCouponDb.type as "PERCENT" | "FIXED" | "BOGO",
        value: activeCouponDb.value,
        minSpend: activeCouponDb.minSpend,
      };
    }
  }

  // Calculate discount
  if (coupon) {
    if (coupon.type === "PERCENT") {
      discount = Math.round(subtotal * (coupon.value / 100) * 100) / 100;
    } else if (coupon.type === "FIXED") {
      discount = Math.min(subtotal, coupon.value);
    } else if (coupon.type === "BOGO") {
      const targetProductId = Math.round(coupon.value);
      const targetItem = items.find((item) => item.productId === targetProductId);
      if (targetItem) {
        const freeQuantity = Math.floor(targetItem.quantity / 2);
        discount = Math.round(freeQuantity * targetItem.price * 100) / 100;
      }
    }
  }

  const total = Math.round((subtotal - discount) * 100) / 100;

  return {
    items,
    subtotal,
    coupon,
    discount,
    total,
    error: error || null,
  };
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getCartState } from "../../../cartHelper";
import { getDb } from "../../../db";

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const state = getCartState();
    json(200, state);
  } catch (err: any) {
    json(500, { error: err.message || "Internal Server Error" });
  }
};

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const body = await request.json();
    const db = getDb();
    const { action } = body;

    if (action === "update") {
      const productId = Number(body.productId);
      const quantity = Number(body.quantity);

      if (isNaN(productId)) {
        return json(400, { error: "Invalid productId" });
      }

      if (quantity <= 0) {
        db.prepare("DELETE FROM CartItem WHERE productId = ?").run(productId);
      } else {
        // Verify product exists first to avoid foreign key constraint violation
        const prod = db.prepare("SELECT id FROM Product WHERE id = ?").get(productId);
        if (!prod) {
          return json(404, { error: "Product not found" });
        }
        db.prepare(`
          INSERT INTO CartItem (productId, quantity)
          VALUES (?, ?)
          ON CONFLICT(productId) DO UPDATE SET quantity = excluded.quantity
        `).run(productId, quantity);
      }

      const state = getCartState();
      return json(200, state);
    }

    if (action === "applyCoupon") {
      const code = String(body.code || "").trim();

      // Check if coupon exists
      const coupon = db.prepare("SELECT code, minSpend FROM Coupon WHERE code = ?").get(code) as { code: string; minSpend: number } | undefined;
      if (!coupon) {
        const state = getCartState("Invalid coupon code");
        return json(200, state);
      }

      // Check minSpend
      // We calculate current subtotal first
      const stateBefore = getCartState();
      if (stateBefore.subtotal < coupon.minSpend) {
        const state = getCartState("Minimum spend not met");
        return json(200, state);
      }

      // Apply the coupon (clear existing coupon first to ensure at most one active coupon)
      db.prepare("DELETE FROM ActiveCoupon").run();
      db.prepare("INSERT INTO ActiveCoupon (code) VALUES (?)").run(code);

      const state = getCartState();
      return json(200, state);
    }

    if (action === "clear") {
      db.prepare("DELETE FROM CartItem").run();
      db.prepare("DELETE FROM ActiveCoupon").run();

      const state = getCartState();
      return json(200, state);
    }

    // Default response if action is unknown
    const state = getCartState();
    json(200, state);
  } catch (err: any) {
    json(500, { error: err.message || "Internal Server Error" });
  }
};

